import { Hono } from "hono";
import { publicationKeys, verifyAuditRoot, type AuditRoot } from "./publication-trust";
// Generated by the genuine TanStack Start production build.
// @ts-ignore -- emitted server module is generated before deployment
import startHandler from "../dist/server/server.js";

export interface D1Database {
  prepare(query: string): {
    bind(...values: unknown[]): {
      all<T = Record<string, unknown>>(): Promise<{ results: T[] }>;
    };
    all<T = Record<string, unknown>>(): Promise<{ results: T[] }>;
  };
}

export interface Fetcher {
  fetch(request: Request | string): Promise<Response>;
}

export interface Env {
  NGSTACK_D1?: D1Database;
  NGSTACK_PUBLICATION_KEYS_JSON?: string;
  ASSETS?: Fetcher;
  ENVIRONMENT: string;
  COMMONS_VERSION: string;
  LICENSE_SPDX: string;
  SOVEREIGN_NON_IMPERSONATION_HEADER: string;
}

const app = new Hono<{ Bindings: Env }>();

// Global Security, Non-Impersonation & CC0-1.0 Headers Middleware
app.use("*", async (c, next) => {
  await next();
  c.header(
    "X-NgStack-Non-Impersonation",
    (c.env?.SOVEREIGN_NON_IMPERSONATION_HEADER ??
      "Independent-Open-Specification-Commons; Not-Govt-Portal; Not-Payment-Switch").replace(/[^\x20-\x7E]/g, " ")
  );
  c.header("X-NgStack-License", "CC0-1.0-Public-Domain");
  c.header("X-Content-Type-Options", "nosniff");
  c.header("Referrer-Policy", "strict-origin-when-cross-origin");
  c.header("Access-Control-Allow-Origin", "*");
  if (/^\/(api|v1|\.well-known)\//.test(new URL(c.req.url).pathname)) c.header("Cache-Control", "no-store");
});

// Explicit configured issuer keys only. No keys are generated or inferred here.
app.get("/.well-known/ngstack-keys.json", (c) => {
 const keys=publicationKeys(c.env?.NGSTACK_PUBLICATION_KEYS_JSON);
 if(!keys.length)return c.json({status:"NOT_PROVISIONED"},503);
 return c.json({id:"did:web:nigeriastack.org",verificationMethod:keys.map(key=>({id:key.id,type:"JsonWebKey2020",controller:"did:web:nigeriastack.org",publicKeyJwk:key.jwk})),scope:"Configured issuer registry; key ownership requires external governance verification"});
});

const merkleHandler=async(c:any)=>{
 const keys=publicationKeys(c.env?.NGSTACK_PUBLICATION_KEYS_JSON);
 if(!c.env?.NGSTACK_D1||keys.length<2)return c.json({status:"NOT_PROVISIONED"},503);
 const {results}=await c.env.NGSTACK_D1.prepare("SELECT * FROM daily_merkle_audit_roots ORDER BY epoch_date DESC LIMIT 1").all();
 const row=results[0] as AuditRoot|undefined;
 if(!row)return c.json({status:"NOT_PUBLISHED"},503);
 if(!await verifyAuditRoot(row,keys))return c.json({status:"PUBLICATION_VERIFICATION_FAILED"},503);
 return c.json({epochDate:row.epoch_date,merkleRootSha256:row.merkle_root_sha256,specificationCommitSha:row.specification_commit_sha,publishedAtUtc:row.published_at_utc,witnessSignatures:JSON.parse(row.ed25519_witness_signatures_json),verification:"SIGNATURE_AND_FRESHNESS_ONLY",limitations:"Signature validity does not establish completeness of the underlying event log, legal admissibility or actual treasury settlement."});
};
app.get("/v1/audit/merkle-root",merkleHandler);
app.get("/v1/audit/treasury-merkle-root",merkleHandler);

// Commons Summary & D1 Health Endpoint (/api/v1/summary)
app.get("/api/v1/summary", async (c) => {
  if (!c.env?.NGSTACK_D1) return c.json({status: "DATABASE_UNAVAILABLE"}, 503);
  const db = c.env.NGSTACK_D1;
  const tables = {rfcs: 'normative_rfcs', industries: 'industry_capability_ledger',
    statesAndFct: 'subnational_state_atlas', constitutionalLgas: 'constitutional_lga_774_registry',
    lgaServiceModules: 'lga_service_modules_14', totalFtsIndexedRows: 'ngstack_global_search_fts'};
  const entries = await Promise.all(Object.entries(tables).map(async ([label, table]) => {
    const {results} = await db.prepare(`SELECT COUNT(*) AS count FROM ${table}`).all();
    return [label, Number(results[0]?.count ?? 0)];
  }));
  return c.json({commonsVersion: c.env.COMMONS_VERSION, counts: Object.fromEntries(entries),
    datasetVerification: "SOURCE_PROVENANCE_REVIEW_REQUIRED"});
});

// D1 FTS5 Edge Search (latency unmeasured) Endpoint (/api/v1/search?q=...)
app.get("/api/v1/search", async (c) => {
  const rawQuery = (c.req.query("q") ?? "").trim();
  if (!rawQuery) {
    return c.json({ query: "", count: 0, results: [] });
  }
  if (c.env?.NGSTACK_D1) {
    try {
      const sanitized = rawQuery
        .replace(/[^a-zA-Z0-9\s_-]/g, " ")
        .trim()
        .split(/\s+/)
        .filter(Boolean)
        .map((t) => `"${t}"*`)
        .join(" ");
      if (sanitized) {
        const { results } = await c.env.NGSTACK_D1.prepare(
          "SELECT entity_type, entity_id, canonical_url, title_civic, body_searchable, statutory_tags FROM ngstack_global_search_fts WHERE ngstack_global_search_fts MATCH ? LIMIT 25"
        )
          .bind(sanitized)
          .all();
        return c.json({ query: rawQuery, count: results.length, results });
      }
    } catch {
      // Fallback to LIKE query if FTS syntax is special
      const likeTerm = `%${rawQuery}%`;
      const { results } = await c.env.NGSTACK_D1.prepare(
        "SELECT entity_type, entity_id, canonical_url, title_civic, body_searchable, statutory_tags FROM ngstack_global_search_fts WHERE title_civic LIKE ? OR body_searchable LIKE ? OR entity_id LIKE ? LIMIT 25"
      )
        .bind(likeTerm, likeTerm, likeTerm)
        .all();
      return c.json({ query: rawQuery, count: results.length, results });
    }
  }
  return c.json({ status: "DATABASE_UNAVAILABLE" }, 503);
});

